// Draft for abap-mcp-adt-powerup: src/handlers/table/readonly/handleGetRemoteTableContents.ts
// Ported from sc4sap_hanta bin/sc4sap-cli.cjs (GetRemoteTableContents, commit 1bba78f).
// Register it next to GetTableContents in the read-only handler group and the tool registry.
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as z from 'zod';
import type { HandlerContext } from '../../../lib/handlers/interfaces';
import {
  activeProfile,
  checkTables,
  evaluateHits,
} from '../../../lib/policy/tableBlocklist';
import { getActiveAlias } from '../../../lib/profile';
import { callDispatch } from '../../../lib/rfcBackend';
import { ErrorCode, McpError } from '../../../lib/utils';

// Same cap as the ABAP REMOTE_READ action; larger extracts page with skip_rows.
const MAX_ROWS = 5000;
// Rows returned when max_rows is not given: enough to see the data shape without a large dump.
const DEFAULT_ROWS = 100;
// RFC_READ_TABLE takes the WHERE clause as OPTIONS lines of at most 72 characters.
const OPTION_WIDTH = 72;
// Saved destinations kept per profile; older ones drop off so the picker list stays short.
const DEST_KEEP = 10;

export const TOOL_DEFINITION = {
  name: 'GetRemoteTableContents',
  available_in: ['onprem'] as const,
  description:
    '[read-only; needs the REMOTE_READ action in ZMCP_ADT_DISPATCH] Read rows of one table in another ' +
    'SAP system through an SM59 RFC destination (ABAP connection) with RFC_READ_TABLE, for building ' +
    'realistic test data. Never guess the destination: when the user has not named one, call without ' +
    'it — the error lists the destinations saved for this profile — and let the user pick one of them ' +
    'or enter another. A destination is saved after its first successful read. Business tables are ' +
    'allowed; the table blocklist still applies. One table per call (no joins); a row longer than 512 ' +
    'characters fails, so pick fields. Filter on key / indexed fields (large tables time out otherwise) ' +
    'and page large extracts with skip_rows.',
  inputSchema: {
    table_name: z.string().describe('Table in the remote system, e.g. VBAK.'),
    fields: z
      .array(z.string())
      .optional()
      .describe('Fields to read; all fields when omitted (fails above 512 characters per row).'),
    where: z
      .string()
      .optional()
      .describe("Open SQL condition without WHERE, e.g. VKORG = '1000'. No sub-queries."),
    max_rows: z
      .number()
      .optional()
      .describe(`Rows to return (default ${DEFAULT_ROWS}, max ${MAX_ROWS}).`),
    skip_rows: z.number().optional().describe('Rows to skip first, for paging (default 0).'),
    destination: z
      .string()
      .optional()
      .describe(
        'SM59 RFC destination (ABAP connection, case-sensitive) chosen by the user, e.g. PRDCLNT100. ' +
          'Omit it to get the saved list for this profile (profile config.json → remoteDestinations).',
      ),
    acknowledge_risk: z
      .boolean()
      .optional()
      .describe(
        "Set to true ONLY after the user has explicitly authorized row extraction from an 'ask'-tier protected table.",
      ),
  },
} as const;

/** Path of the active profile's config.json, or null when no profile alias is active (legacy sap.env). */
function profileConfigPath(): string | null {
  const alias = getActiveAlias();
  if (!alias) return null;
  const home = process.env.SC4SAP_HOME_DIR || path.join(os.homedir(), '.sc4sap');
  return path.join(home, 'profiles', alias, 'config.json');
}

/** Destinations saved for the active profile, most recently used first (empty when none / unreadable). */
export function readRemoteDestinations(): string[] {
  const file = profileConfigPath();
  if (!file || !fs.existsSync(file)) return [];
  try {
    const list = JSON.parse(fs.readFileSync(file, 'utf8')).remoteDestinations;
    return Array.isArray(list) ? list.filter((d) => typeof d === 'string' && d) : [];
  } catch {
    return [];
  }
}

/**
 * Moves `dest` to the front of the saved list and writes config.json back, keeping every other key.
 * A failed write is only reported: the read itself already succeeded.
 */
export function rememberRemoteDestination(dest: string): void {
  const file = profileConfigPath();
  if (!file || !fs.existsSync(file)) return;
  try {
    const cfg = JSON.parse(fs.readFileSync(file, 'utf8'));
    const prev: string[] = Array.isArray(cfg.remoteDestinations) ? cfg.remoteDestinations : [];
    const next = [dest, ...prev.filter((d) => d !== dest)].slice(0, DEST_KEEP);
    if (JSON.stringify(next) === JSON.stringify(prev)) return;
    cfg.remoteDestinations = next;
    const tmp = `${file}.tmp`;
    fs.writeFileSync(tmp, `${JSON.stringify(cfg, null, 2)}\n`, 'utf8');
    fs.renameSync(tmp, file);
  } catch (e) {
    process.stderr.write(`[mcp-abap-adt] remote destination not saved: ${String(e)}\n`);
  }
}

/**
 * Splits an Open SQL condition into RFC_READ_TABLE OPTIONS lines of at most `width` characters.
 * Breaks only at whitespace outside quoted literals, so a literal is never cut in two.
 * @returns the lines (empty array for an empty condition)
 */
export function splitWhereLines(condition: string | undefined, width = OPTION_WIDTH): string[] {
  const tokens: string[] = [];
  let cur = '';
  let quoted = false;
  for (const ch of String(condition ?? '')) {
    if (ch === "'") quoted = !quoted; // '' inside a literal toggles twice and stays quoted
    if (!quoted && /\s/.test(ch)) {
      if (cur) tokens.push(cur);
      cur = '';
      continue;
    }
    cur += ch;
  }
  if (quoted) throw new McpError(ErrorCode.InvalidParams, 'where: unclosed quote in the condition');
  if (cur) tokens.push(cur);
  const lines: string[] = [];
  let line = '';
  for (const t of tokens) {
    if (t.length > width) {
      throw new McpError(
        ErrorCode.InvalidParams,
        `where: "${t.slice(0, 40)}…" is longer than ${width} characters; RFC_READ_TABLE cannot split it`,
      );
    }
    if (!line) line = t;
    else if (line.length + 1 + t.length <= width) line += ` ${t}`;
    else {
      lines.push(line);
      line = t;
    }
  }
  if (line) lines.push(line);
  return lines;
}

/**
 * GetRemoteTableContents: rows of one table in another SAP system via the dispatcher action
 * REMOTE_READ (RFC_READ_TABLE over the SM59 ABAP destination the user named).
 * @returns destination, table, fields [{name,type,length,text}], rows, count — or, without a
 *   destination, an error listing the saved destinations so the agent can ask the user.
 */
export async function handleGetRemoteTableContents(context: HandlerContext, args: any) {
  const { connection, logger } = context;
  try {
    if (!args?.table_name) {
      throw new McpError(ErrorCode.InvalidParams, 'table_name is required');
    }
    const destination = String(args.destination ?? '').trim(); // SM59 names are case-sensitive
    if (!destination) {
      // No default destination on purpose: the agent shows the saved list and lets the user pick.
      const saved = readRemoteDestinations();
      throw new McpError(
        ErrorCode.InvalidParams,
        saved.length
          ? `destination is required. Saved for this profile (most recent first): ${saved.join(', ')}. ` +
              'Ask the user to pick one of them or to name another SM59 destination.'
          : 'destination is required and none is saved for this profile yet. Ask the user for the SM59 destination name.',
      );
    }

    const tableName = String(args.table_name).trim().toUpperCase();
    const verdict = evaluateHits(checkTables([tableName]), args.acknowledge_risk === true, activeProfile());
    if (verdict.kind === 'deny' || verdict.kind === 'ask') {
      logger?.warn(`GetRemoteTableContents ${verdict.kind}: ${tableName}`);
      throw new McpError(ErrorCode.InvalidRequest, verdict.message);
    }
    if (verdict.kind === 'approved') {
      process.stderr.write(
        `[mcp-abap-adt][blocklist] AUDIT: user-acknowledged GetRemoteTableContents on ${verdict.tables.join(',')}\n`,
      );
    }

    const requested = Number(args.max_rows) > 0 ? Math.floor(Number(args.max_rows)) : DEFAULT_ROWS;
    const params = {
      destination,
      table_name: tableName,
      field_list: Array.isArray(args.fields)
        ? args.fields.map((f: unknown) => String(f).trim().toUpperCase()).filter(Boolean)
        : [],
      options: splitWhereLines(args.where),
      max_rows: Math.min(requested, MAX_ROWS),
      skip_rows: Number(args.skip_rows) > 0 ? Math.floor(Number(args.skip_rows)) : 0,
    };
    // TODO(port): match legacyTableRead's handling of a non-zero dispatcher subrc if callDispatch
    // does not already throw on it, so REMOTE_READ messages reach the user unchanged.
    const { result } = await callDispatch(connection, 'REMOTE_READ', params);
    rememberRemoteDestination(destination); // saved only after a read worked, so typos never enter the list
    return {
      isError: false,
      content: [{ type: 'text', text: typeof result === 'string' ? result : JSON.stringify(result) }],
    };
  } catch (error) {
    logger?.error('GetRemoteTableContents failed', error as any);
    return { isError: true, content: [{ type: 'text', text: `ADT error: ${String(error)}` }] };
  }
}

*&---------------------------------------------------------------------*
*& REMOTE_READ action for ZMCP_ADT_DISPATCH (S/4 and ECC dispatchers)
*&---------------------------------------------------------------------*
* Source: the live HKD dispatcher (activated, verified against a remote
* client). Paste into sc4sap/abap/zmcp_adt_dispatch.abap and
* sc4sap/abap/zmcp_adt_dispatch_ecc.abap:
*
* 1) In the FM body, inside CASE iv_action, add the branch:
*
*        WHEN 'REMOTE_READ'.     PERFORM remote_read     USING iv_params CHANGING ev_subrc ev_message ev_result.
*
* 2) Append the two FORMs below at the end of the source.
*
* Needs /ui2/cl_json (already used by both dispatchers) and the standard
* RFC_READ_TABLE in the remote system - nothing is installed there.
*&---------------------------------------------------------------------*

*&---------------------------------------------------------------------*
*& Form REMOTE_READ - read-only table rows from another system via RFC
*&---------------------------------------------------------------------*
* Reads rows of one table in another SAP system through an RFC
* destination the user names (SM59 ABAP connection, e.g. PRDCLNT100)
* with the standard RFC_READ_TABLE, so realistic test data sets can be
* built without installing anything there.
* Business tables are allowed on purpose; credential / user master
* tables stay closed and sub-queries are refused. The caller (MCP tool /
* CLI) applies the table blocklist before calling.
* params: destination, table_name, field_list (string table),
*         options (string table, WHERE lines of at most 72 characters),
*         max_rows, skip_rows
* result: destination, table, fields [{name,type,length,text}],
*         rows (array of objects, values as text), count
FORM remote_read USING iv_params TYPE string CHANGING ev_subrc TYPE i ev_message TYPE string ev_result TYPE string.
  TYPES ty_names TYPE STANDARD TABLE OF string WITH DEFAULT KEY.
  DATA: BEGIN OF ls_input,
          destination TYPE string,
          table_name  TYPE string,
          field_list  TYPE ty_names,
          options     TYPE ty_names,
          max_rows    TYPE i,
          skip_rows   TYPE i,
        END OF ls_input.
  DATA: lv_dest     TYPE rfcdest,
        lv_tab      TYPE tabname,
        lv_line     TYPE string,
        lv_all      TYPE string,
        lv_max      TYPE i,
        lv_skip     TYPE i,
        lv_msg(255) TYPE c,
        lv_val      TYPE string,
        lv_off      TYPE i,
        lv_len      TYPE i,
        lv_num      TYPE string,
        lv_sep      TYPE string,
        lv_fsep     TYPE string,
        lt_opt      TYPE STANDARD TABLE OF rfc_db_opt,
        ls_opt      TYPE rfc_db_opt,
        lt_fld      TYPE STANDARD TABLE OF rfc_db_fld,
        ls_fld      TYPE rfc_db_fld,
        lt_dat      TYPE STANDARD TABLE OF tab512,
        ls_dat      TYPE tab512,
        lt_json     TYPE ty_names.
  DATA lv_rfctype TYPE rfcdes-rfctype.
  " Destinations must be ABAP connections (SM59 type 3): RFC_READ_TABLE
  " exists only in an SAP system.
  CONSTANTS lc_abap_conn TYPE rfcdes-rfctype VALUE '3'.
  " Row cap per call (same as TABLE_READ); larger extracts page with skip_rows.
  CONSTANTS lc_max_rows TYPE i VALUE 5000.
  " Rows when the caller sends none: enough to see the data shape.
  CONSTANTS lc_default_rows TYPE i VALUE 100.
  " RFC_READ_TABLE OPTIONS line width (RFC_DB_OPT-TEXT is CHAR 72).
  CONSTANTS lc_option_width TYPE i VALUE 72.
  " RFC_READ_TABLE data line width (TAB512-WA is CHAR 512).
  CONSTANTS lc_data_width TYPE i VALUE 512.

  /ui2/cl_json=>deserialize( EXPORTING json = iv_params CHANGING data = ls_input ).

  " The caller names the destination (the tool asks the user); it must be an
  " ABAP connection maintained in SM59.
  lv_dest = condense( ls_input-destination ).
  IF lv_dest IS INITIAL.
    ev_subrc = 4. ev_message = 'REMOTE_READ: destination is required'. ev_result = '{}'.
    RETURN.
  ENDIF.
  SELECT SINGLE rfctype FROM rfcdes INTO lv_rfctype WHERE rfcdest = lv_dest.
  IF sy-subrc <> 0.
    ev_subrc = 4. ev_message = |REMOTE_READ: destination { lv_dest } is not defined in SM59|. ev_result = '{}'.
    RETURN.
  ENDIF.
  IF lv_rfctype <> lc_abap_conn.
    ev_subrc = 4. ev_message = |REMOTE_READ: destination { lv_dest } is not an ABAP connection (type { lv_rfctype })|. ev_result = '{}'.
    RETURN.
  ENDIF.

  lv_tab = to_upper( condense( ls_input-table_name ) ).
  IF lv_tab IS INITIAL.
    ev_subrc = 4. ev_message = 'REMOTE_READ: table_name is required'. ev_result = '{}'.
    RETURN.
  ENDIF.
  " Credentials, user master and security tables stay closed whatever the purpose.
  IF lv_tab = 'RFCDES' OR lv_tab = 'RSECTAB' OR lv_tab = 'RSECACTB'
     OR lv_tab CP 'USR*' OR lv_tab CP 'UST*' OR lv_tab CP 'AGR_*'
     OR lv_tab CP 'SSF_PSE*' OR lv_tab CP 'STRUST*' OR lv_tab CP 'SNC*'
     OR lv_tab CP 'TRUSTED*' OR lv_tab CP 'RSAU*'.
    ev_subrc = 4. ev_message = |REMOTE_READ: table { lv_tab } is not allowed|. ev_result = '{}'.
    RETURN.
  ENDIF.

  " WHERE lines: width check, and no sub-queries (checked on the joined text,
  " so a keyword split across two lines is still caught).
  LOOP AT ls_input-options INTO lv_line.
    IF strlen( lv_line ) > lc_option_width.
      ev_subrc = 4. ev_message = |REMOTE_READ: options lines must be at most { lc_option_width } characters|. ev_result = '{}'.
      RETURN.
    ENDIF.
    CONCATENATE lv_all lv_line INTO lv_all.
    CLEAR ls_opt.
    ls_opt-text = lv_line.
    APPEND ls_opt TO lt_opt.
  ENDLOOP.
  lv_all = to_upper( lv_all ).
  IF lv_all CS 'SELECT' OR lv_all CS 'JOIN'.
    ev_subrc = 4. ev_message = 'REMOTE_READ: sub-queries are not allowed in the condition'. ev_result = '{}'.
    RETURN.
  ENDIF.

  LOOP AT ls_input-field_list INTO lv_line.
    CLEAR ls_fld.
    ls_fld-fieldname = to_upper( condense( lv_line ) ).
    APPEND ls_fld TO lt_fld.
  ENDLOOP.

  lv_max = ls_input-max_rows.
  IF lv_max <= 0. lv_max = lc_default_rows. ENDIF.
  IF lv_max > lc_max_rows. lv_max = lc_max_rows. ENDIF.
  lv_skip = ls_input-skip_rows.
  IF lv_skip < 0. lv_skip = 0. ENDIF.

  CALL FUNCTION 'RFC_READ_TABLE'
    DESTINATION lv_dest
    EXPORTING
      query_table           = lv_tab
      rowcount              = lv_max
      rowskips              = lv_skip
    TABLES
      options               = lt_opt
      fields                = lt_fld
      data                  = lt_dat
    EXCEPTIONS
      table_not_available   = 1
      table_without_data    = 2
      option_not_valid      = 3
      field_not_valid       = 4
      not_authorized        = 5
      data_buffer_exceeded  = 6
      system_failure        = 7 MESSAGE lv_msg
      communication_failure = 8 MESSAGE lv_msg
      OTHERS                = 9.
  CASE sy-subrc.
    WHEN 0.
    WHEN 1. ev_subrc = 4. ev_message = |REMOTE_READ: table { lv_tab } is not available on { lv_dest }|.
    WHEN 2. ev_subrc = 4. ev_message = |REMOTE_READ: { lv_tab } has no database table on { lv_dest }|.
    WHEN 3. ev_subrc = 4. ev_message = 'REMOTE_READ: the WHERE condition is not valid'.
    WHEN 4. ev_subrc = 4. ev_message = |REMOTE_READ: a requested field is not on { lv_tab }|.
    WHEN 5. ev_subrc = 4. ev_message = |REMOTE_READ: the RFC user of { lv_dest } may not read { lv_tab } (S_TABU_DIS)|.
    WHEN 6. ev_subrc = 4. ev_message = |REMOTE_READ: a row is longer than { lc_data_width } characters - choose fewer fields|.
    WHEN 7. ev_subrc = 8. ev_message = |REMOTE_READ: system failure on { lv_dest }: { lv_msg }|.
    WHEN 8. ev_subrc = 8. ev_message = |REMOTE_READ: communication failure to { lv_dest }: { lv_msg }|.
    WHEN OTHERS. ev_subrc = 8. ev_message = |REMOTE_READ: RFC_READ_TABLE failed, sy-subrc { sy-subrc }|.
  ENDCASE.
  IF ev_subrc <> 0.
    ev_result = '{}'.
    RETURN.
  ENDIF.

  " Field list: name, ABAP type, length and short text.
  APPEND |\{"destination":"{ lv_dest }","table":"{ lv_tab }","fields":[| TO lt_json.
  CLEAR lv_sep.
  LOOP AT lt_fld INTO ls_fld.
    lv_val = ls_fld-fieldtext.
    PERFORM remote_read_escape CHANGING lv_val.
    lv_len = ls_fld-length.
    lv_num = lv_len.
    CONDENSE lv_num.
    APPEND |{ lv_sep }\{"name":"{ ls_fld-fieldname }","type":"{ ls_fld-type }","length":{ lv_num },"text":"{ lv_val }"\}| TO lt_json.
    lv_sep = ','.
  ENDLOOP.

  " Rows: each field cut from the fixed-width data line at its offset.
  APPEND '],"rows":[' TO lt_json.
  CLEAR lv_sep.
  LOOP AT lt_dat INTO ls_dat.
    APPEND |{ lv_sep }\{| TO lt_json.
    CLEAR lv_fsep.
    LOOP AT lt_fld INTO ls_fld.
      lv_off = ls_fld-offset.
      lv_len = ls_fld-length.
      IF lv_off + lv_len > lc_data_width.
        lv_len = lc_data_width - lv_off.
      ENDIF.
      CLEAR lv_val.
      IF lv_len > 0.
        lv_val = ls_dat-wa+lv_off(lv_len).
        SHIFT lv_val LEFT DELETING LEADING space.
        PERFORM remote_read_escape CHANGING lv_val.
      ENDIF.
      APPEND |{ lv_fsep }"{ ls_fld-fieldname }":"{ lv_val }"| TO lt_json.
      lv_fsep = ','.
    ENDLOOP.
    APPEND '}' TO lt_json.
    lv_sep = ','.
  ENDLOOP.

  lv_num = lines( lt_dat ).
  CONDENSE lv_num.
  APPEND |],"count":{ lv_num }\}| TO lt_json.
  CONCATENATE LINES OF lt_json INTO ev_result.
  ev_subrc = 0.
  ev_message = 'OK'.
ENDFORM.

*&---------------------------------------------------------------------*
*& Form REMOTE_READ_ESCAPE - escape a text value for a JSON string
*&---------------------------------------------------------------------*
FORM remote_read_escape CHANGING cv_text TYPE string.
  DATA lv_cr TYPE c LENGTH 1.
  lv_cr = cl_abap_char_utilities=>cr_lf. " first character = carriage return
  REPLACE ALL OCCURRENCES OF `\` IN cv_text WITH `\\`.
  REPLACE ALL OCCURRENCES OF `"` IN cv_text WITH `\"`.
  REPLACE ALL OCCURRENCES OF cl_abap_char_utilities=>horizontal_tab IN cv_text WITH `\t`.
  REPLACE ALL OCCURRENCES OF cl_abap_char_utilities=>newline IN cv_text WITH `\n`.
  REPLACE ALL OCCURRENCES OF lv_cr IN cv_text WITH `\r`.
ENDFORM.
